    for i in 0..10_000_000 {
        let mut name: String = (0..32)
            .map(|_| {
                let r = rng.random_range(0..('Z' as u8 - 'A' as u8 + 1));
                (b'A' + r) as char
            })
            .collect();
        // Ensure the key is unique.
        while tree.bostree_lookup(&name).is_some() {
            name = (0..32)
