BOSNode *bostree_node_weak_unref(BOSTree *tree, BOSNode *node) {
	node->weak_ref_count--;
	if(node->weak_ref_count == 0) {
		if(tree->free_function) {
			tree->free_function(node);
		}
		free(node);
	}
