            };
            let old_parent = parent_of(node);
            self.transplant(node, child);
            old_parent
        };

        {
            let mut node_ref = node.borrow_mut();
            node_ref.weak_ref_node_valid = 0;
            node_ref.left_child_node = None;
            node_ref.right_child_node = None;
            node_ref.parent_node = None;
            node_ref.left_child_count = 0;
            node_ref.right_child_count = 0;
            node_ref.depth = 0;
