    pub fn bostree_print(&self) {
        fn print_node(node: &Rc<RefCell<BOSNode>>) {
            let (key, left_count, right_count, depth, parent, left, right) = {
                let node_ref = node.borrow();
                (
                    node_ref.key.clone(),
                    node_ref.left_child_count,
                    node_ref.right_child_count,
                    node_ref.depth,
                    node_ref.parent_node.as_ref().and_then(Weak::upgrade),
                    node_ref.left_child_node.clone(),
                    node_ref.right_child_node.clone(),
                )
            };

            println!(
                "  {} [label=\"\\N ({},{},{})\"];",
                key, left_count, right_count, depth
            );
            if let Some(parent) = parent {
                println!("  {} -> {} [color=green];", key, parent.borrow().key);
            }
            if let Some(left) = left {
                println!("  {} -> {}", key, left.borrow().key);
                print_node(&left);
            }
            if let Some(right) = right {
                println!("  {} -> {}", key, right.borrow().key);
                print_node(&right);
            }
        }

        if let Some(root) = &self.root_node {
            println!("digraph {{");
            println!("  ordering = out;");
            print_node(root);
            println!("}}");
        }
    }

    fn transplant(&mut self, old_node: &Rc<RefCell<BOSNode>>, new_node: Option<Rc<RefCell<BOSNode>>>) {
        let old_parent = parent_of(old_node);
        match old_parent {
            Some(parent) => {
                if is_left_child(&parent, old_node) {
                    parent.borrow_mut().left_child_node = new_node.clone();
                } else {
                    parent.borrow_mut().right_child_node = new_node.clone();
                }
                set_parent(&new_node, Some(&parent));
            }
            None => {
                self.root_node = new_node.clone();
                set_parent(&new_node, None);
            }
        }
    }

    fn remove_node_with_two_children(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        let right_child = node.borrow().right_child_node.clone().expect("right child exists");
        let candidate = minimum_node(right_child);
        let candidate_parent = parent_of(&candidate).expect("candidate has a parent");
        let candidate_was_direct_child = Rc::ptr_eq(&candidate_parent, node);
        let rebalance_start;

        if candidate_was_direct_child {
            rebalance_start = Some(candidate.clone());
        } else {
            let candidate_right = candidate.borrow().right_child_node.clone();
            rebalance_start = Some(candidate_parent.clone());
            self.transplant(&candidate, candidate_right);

            let node_right = node.borrow().right_child_node.clone();
            candidate.borrow_mut().right_child_node = node_right;
            let candidate_right = candidate.borrow().right_child_node.clone();
            set_parent(&candidate_right, Some(&candidate));
        }

        self.transplant(node, Some(candidate.clone()));

        let node_left = node.borrow().left_child_node.clone();
        candidate.borrow_mut().left_child_node = node_left;
        let candidate_left = candidate.borrow().left_child_node.clone();
        set_parent(&candidate_left, Some(&candidate));

        update_node(&candidate);
        rebalance_start
    }

    fn rotate_left(&mut self, node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
        let pivot = node
            .borrow_mut()
            .right_child_node
            .take()
            .expect("left rotation requires a right child");
        let pivot_left = pivot.borrow_mut().left_child_node.take();

        {
            let mut node_ref = node.borrow_mut();
            node_ref.right_child_node = pivot_left;
            set_parent(&node_ref.right_child_node, Some(node));
        }

        let old_parent = parent_of(node);
        match old_parent {
            Some(parent) => {
                if is_left_child(&parent, node) {
                    parent.borrow_mut().left_child_node = Some(pivot.clone());
                } else {
                    parent.borrow_mut().right_child_node = Some(pivot.clone());
                }
                pivot.borrow_mut().parent_node = Some(Rc::downgrade(&parent));
            }
            None => {
                self.root_node = Some(pivot.clone());
                pivot.borrow_mut().parent_node = None;
            }
        }

        pivot.borrow_mut().left_child_node = Some(node.clone());
        node.borrow_mut().parent_node = Some(Rc::downgrade(&pivot));

        update_node(node);
        update_node(&pivot);
        pivot
    }

    fn rotate_right(&mut self, node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
        let pivot = node
            .borrow_mut()
            .left_child_node
            .take()
            .expect("right rotation requires a left child");
        let pivot_right = pivot.borrow_mut().right_child_node.take();

        {
            let mut node_ref = node.borrow_mut();
            node_ref.left_child_node = pivot_right;
            set_parent(&node_ref.left_child_node, Some(node));
        }

        let old_parent = parent_of(node);
        match old_parent {
            Some(parent) => {
                if is_left_child(&parent, node) {
                    parent.borrow_mut().left_child_node = Some(pivot.clone());
                } else {
                    parent.borrow_mut().right_child_node = Some(pivot.clone());
                }
                pivot.borrow_mut().parent_node = Some(Rc::downgrade(&parent));
            }
            None => {
                self.root_node = Some(pivot.clone());
                pivot.borrow_mut().parent_node = None;
            }
        }

        pivot.borrow_mut().right_child_node = Some(node.clone());
        node.borrow_mut().parent_node = Some(Rc::downgrade(&pivot));

        update_node(node);
        update_node(&pivot);
        pivot
    }

    fn rebalance_from(&mut self, mut current: Option<Rc<RefCell<BOSNode>>>) {
        while let Some(node) = current {
            update_node(&node);
            let balance = balance(&node);
            let subtree_root = if balance < -1 {
                let left = node.borrow().left_child_node.clone().expect("left child exists");
                if balance(&left) > 0 {
                    self.rotate_left(&left);
                }
                self.rotate_right(&node)
            } else if balance > 1 {
                let right = node.borrow().right_child_node.clone().expect("right child exists");
                if balance(&right) < 0 {
                    self.rotate_right(&right);
                }
                self.rotate_left(&node)
            } else {
                node
            };
            current = parent_of(&subtree_root);
        }
    }
}

/// Increase the weak reference count for a node and return the node.
pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let mut node_ref = node.borrow_mut();
    assert!(node_ref.weak_ref_count < 127);
    assert!(node_ref.weak_ref_count > 0);
    node_ref.weak_ref_count += 1;
    drop(node_ref);
    node.clone()
}

/// Return the next node in an in-order traversal.
pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(mut current) = node.borrow().right_child_node.clone() {
        loop {
            let left = current.borrow().left_child_node.clone();
            match left {
                Some(next) => current = next,
                None => return Some(current),
            }
        }
    }

    let mut current = node.clone();
    while let Some(parent) = parent_of(&current) {
        if is_left_child(&parent, &current) {
            return Some(parent);
        }
        current = parent;
    }
    None
}

/// Return the previous node in an in-order traversal.
pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(mut current) = node.borrow().left_child_node.clone() {
        loop {
            let right = current.borrow().right_child_node.clone();
            match right {
                Some(next) => current = next,
                None => return Some(current),
            }
        }
    }

    let mut current = node.clone();
    while let Some(parent) = parent_of(&current) {
        if !is_left_child(&parent, &current) {
            return Some(parent);
        }
        current = parent;
    }
    None
}

/// Return the rank (in-order index) of the given node.
pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut current = node.clone();
    while let Some(parent) = parent_of(&current) {
        if !is_left_child(&parent, &current) {
            counter += parent.borrow().left_child_count + 1;
        }
        current = parent;
    }
    counter
}
