pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;

/// Type alias for a free function which will be called on nodes
/// that are removed.
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

fn node_size(node: &Option<Rc<RefCell<BOSNode>>>) -> u32 {
    node.as_ref().map_or(0, |node| {
        let node_ref = node.borrow();
        node_ref.left_child_count + node_ref.right_child_count + 1
    })
}

fn child_depth(node: &Option<Rc<RefCell<BOSNode>>>) -> u32 {
    node.as_ref().map_or(0, |node| node.borrow().depth + 1)
}

fn balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let node_ref = node.borrow();
    child_depth(&node_ref.right_child_node) as i32 - child_depth(&node_ref.left_child_node) as i32
}

fn update_node(node: &Rc<RefCell<BOSNode>>) {
    let (left_count, right_count, left_depth, right_depth) = {
        let node_ref = node.borrow();
        (
            node_size(&node_ref.left_child_node),
            node_size(&node_ref.right_child_node),
            child_depth(&node_ref.left_child_node),
            child_depth(&node_ref.right_child_node),
        )
    };

    let mut node_ref = node.borrow_mut();
    node_ref.left_child_count = left_count;
    node_ref.right_child_count = right_count;
    node_ref.depth = max(left_depth, right_depth);
}

fn parent_of(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    node.borrow().parent_node.as_ref().and_then(Weak::upgrade)
}

