pub mod interfaces;

use crate::bostree::{
    bostree_next_node, bostree_previous_node, bostree_rank, BOSNode, BOSTree,
};
use std::cell::RefCell;
use std::cmp::max;
use std::rc::Rc;

pub fn test_tree_sanity(tree: &BOSTree) {
    fn verify_metadata(node: &Rc<RefCell<BOSNode>>) -> (u32, u32) {
        let (key, left, right, parent, reported_left, reported_right, reported_depth) = {
            let node_ref = node.borrow();
            (
                node_ref.key.clone(),
                node_ref.left_child_node.clone(),
                node_ref.right_child_node.clone(),
                node_ref.parent_node.clone(),
                node_ref.left_child_count,
                node_ref.right_child_count,
                node_ref.depth,
            )
        };

        if let Some(parent_weak) = parent {
            if let Some(parent) = parent_weak.upgrade() {
                let left_ok = parent
                    .borrow()
                    .left_child_node
                    .as_ref()
                    .map_or(false, |left| Rc::ptr_eq(node, left));
                let right_ok = parent
                    .borrow()
                    .right_child_node
                    .as_ref()
                    .map_or(false, |right| Rc::ptr_eq(node, right));
                if !left_ok && !right_ok {
                    println!(
                        "Node {} has a parent, {}, but is not one of its children.",
                        key,
                        parent.borrow().key
                    );
                    panic!("Exiting due to errors.");
                }
            }
        }

        let (actual_left_count, left_depth) = left.as_ref().map_or((0, 0), |left| {
            let (count, depth) = verify_metadata(left);
            (count, depth + 1)
        });
        let (actual_right_count, right_depth) = right.as_ref().map_or((0, 0), |right| {
            let (count, depth) = verify_metadata(right);
            (count, depth + 1)
        });
        let actual_depth = max(left_depth, right_depth);

        if actual_depth != reported_depth {
            println!(
                "Node {} reports depth {} when the actual depth is {}",
                key, reported_depth, actual_depth
            );
            panic!("Exiting due to errors.");
        }
        if actual_left_count != reported_left {
            println!(
                "Node {} reports {} left children when there are {}",
                key, reported_left, actual_left_count
            );
            panic!("Exiting due to errors.");
        }
        if actual_right_count != reported_right {
            println!(
                "Node {} reports {} right children when there are {}",
                key, reported_right, actual_right_count
            );
            panic!("Exiting due to errors.");
        }
        if (left_depth as i32 - right_depth as i32).abs() > 1 {
            println!(
                "Node {} violates the balance constraint: {} left depth vs. {} right depth",
                key, left_depth, right_depth
            );
            panic!("Exiting due to errors.");
        }

        (actual_left_count + actual_right_count + 1, actual_depth)
    }

    if let Some(root) = &tree.root_node {
        let (actual_count, _) = verify_metadata(root);
        let reported_count = tree.bostree_node_count();
        if actual_count != reported_count {
            println!(
                "Manual node count yielded {}, order statistics reported {}",
                actual_count, reported_count
            );
            panic!("Exiting due to errors.");
        }
    } else if tree.bostree_node_count() != 0 {
        println!(
            "Manual node count yielded 0, order statistics reported {}",
            tree.bostree_node_count()
        );
        panic!("Exiting due to errors.");
    }

    let mut count = 0;
    let mut current = tree.bostree_select(0);
    while let Some(node) = current {
        count += 1;
        current = bostree_next_node(&node);
    }
    let reported_count = tree.bostree_node_count();
    if count != reported_count {
        println!(
            "Manual node count yielded {}, order statistics reported {}",
            count, reported_count
        );
        panic!("Exiting due to errors.");
    }

    for i in 0..reported_count {
        let node_opt = tree.bostree_select(i);
        if node_opt.is_none() {
            println!(
                "Rank {} node not found, though count is {}",
                i, reported_count
            );
            panic!("Exiting due to errors.");
        }
        let node = node_opt.unwrap();
        let rank = bostree_rank(&node);
        if rank != i {
            println!(
                "Rank for node {} is {} but should be {}",
                node.borrow().key,
                rank,
                i
            );
            panic!("Exiting due to errors.");
        }
        let lookup_node = tree.bostree_lookup(&node.borrow().key);
        if let Some(ln) = lookup_node {
            if !Rc::ptr_eq(&node, &ln) {
                println!("Lookup for {} returned the wrong node.", node.borrow().key);
                panic!("Exiting due to errors.");
            }
        } else {
            println!("Lookup for {} returned None.", node.borrow().key);
            panic!("Exiting due to errors.");
        }
        let next_node = bostree_next_node(&node);
        let select_next = tree.bostree_select(i + 1);
        match (next_node, select_next) {
            (Some(n1), Some(n2)) => {
                if !Rc::ptr_eq(&n1, &n2) {
                    println!(
                        "Next node is {}, but select(i+1) is {}",
                        n1.borrow().key,
                        n2.borrow().key
                    );
                    panic!("Exiting due to errors.");
                }
            }
            (None, None) => {}
            _ => {
                println!("Mismatch between next node and select(i+1) for index {}", i);
                panic!("Exiting due to errors.");
            }
        }
        let prev_node = if i == 0 {
            None
        } else {
            tree.bostree_select(i - 1)
        };
        let node_prev = bostree_previous_node(&node);
        match (prev_node, node_prev) {
            (Some(n1), Some(n2)) => {
                if !Rc::ptr_eq(&n1, &n2) {
                    println!(
                        "Previous node is {}, but select(i-1) is {}",
                        n2.borrow().key,
                        n1.borrow().key
                    );
                    panic!("Exiting due to errors.");
                }
            }
            (None, None) => {}
            _ => {
                println!(
                    "Mismatch between previous node and select(i-1) for index {}",
                    i
                );
                panic!("Exiting due to errors.");
            }
        }
    }
}

